import * as React from "react";

export function GlyphCascadeTailwind({ text = "DETERMINISTIC GLYPH CASCADE" }) {
  const [step, setStep] = React.useState(0);
  React.useEffect(() => {
    const id = setInterval(() => setStep((s) => (s < text.length * 2 ? s + 1 : s)), 30);
    return () => clearInterval(id);
  }, [text]);
  return (
    <span className="font-mono text-base font-semibold tracking-wider text-zinc-100">
      {Array.from(text).map((c, i) => (
        <span key={i} className={step >= i * 2 ? "text-zinc-100" : "text-zinc-500 blur-[1px]"}>
          {c === " " || step >= i * 2 ? c : "01/#%"[(i + step) % 5]}
        </span>
      ))}
    </span>
  );
}

