"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/rotating-words.module.css";

export interface RotatingWordsProps {
  /** Static text rendered before the rotating word */
  prefix?: string;
  /** Words cycled in place */
  words?: string[];
  /** Milliseconds each word stays visible */
  interval?: number;
  /** Color of the rotating word */
  accentColor?: string;
  /** Optional className */
  className?: string;
}

const DEFAULT_WORDS = ["faster", "smoother", "bolder", "today"];

export function RotatingWords({
  prefix = "Ship",
  words = DEFAULT_WORDS,
  interval = 2000,
  accentColor = "#38bdf8",
  className = "",
}: RotatingWordsProps) {
  const prefersReducedMotion = useReducedMotion();
  const list = words.length > 0 ? words : DEFAULT_WORDS;
  const [index, setIndex] = React.useState(0);

  React.useEffect(() => {
    if (prefersReducedMotion || list.length < 2) return;
    const id = setInterval(() => setIndex((n) => (n + 1) % list.length), interval);
    return () => clearInterval(id);
  }, [list.length, interval, prefersReducedMotion]);

  const current = list[index % list.length];
  const label = `${prefix ? `${prefix} ` : ""}${list.join(", ")}`;

  return (
    <span
      style={{ "--mf-rw-accent": accentColor } as React.CSSProperties}
      className={`${styles.root} ${className}`.trim()}
    >
      <span className={styles.srOnly}>{label}</span>
      <span aria-hidden="true" className={styles.visual}>
        {prefix ? <span className={styles.prefix}>{prefix}</span> : null}
        <span className={styles.slot}>
          {list.map((word, i) => (
            <span key={`sizer-${i}`} className={styles.sizer}>
              {word}
            </span>
          ))}
          <AnimatePresence mode="wait" initial={false}>
            <motion.span
              key={`${index}-${current}`}
              className={styles.word}
              initial={prefersReducedMotion ? false : { y: "100%", opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={prefersReducedMotion ? undefined : { y: "-100%", opacity: 0 }}
              transition={{ type: "spring", stiffness: 300, damping: 25 }}
            >
              {current}
            </motion.span>
          </AnimatePresence>
        </span>
      </span>
    </span>
  );
}

.root {
  display: inline-block;
  color: var(--mf-fg, #f4f4f6);
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.2;
}

.visual {
  display: inline-flex;
  align-items: baseline;
  gap: 0.28em;
}

.prefix {
  color: var(--mf-fg, #f4f4f6);
}

/* All words stack invisibly in one grid cell so the slot reserves the
   widest word and swapping words never shifts surrounding layout. */
.slot {
  position: relative;
  display: inline-grid;
  overflow: hidden;
  padding-bottom: 0.08em;
  vertical-align: bottom;
}

.sizer {
  grid-area: 1 / 1;
  visibility: hidden;
  white-space: nowrap;
}

.word {
  grid-area: 1 / 1;
  display: inline-block;
  white-space: nowrap;
  color: var(--mf-rw-accent, var(--mf-accent, #38bdf8));
  will-change: transform, opacity;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .word {
    transform: none !important;
    opacity: 1 !important;
  }
}

