"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/slide-fill-button.module.css";

export interface SlideFillButtonProps {
  /** Button label (ignored when children are provided) */
  label?: string;
  /** Custom button content */
  children?: React.ReactNode;
  /** Edge the fill slides in from */
  direction?: "left" | "right" | "up" | "down";
  /** Fill color */
  fillColor?: string;
  /** Label color while filled */
  fillTextColor?: string;
  /** Fill transition duration in seconds */
  duration?: number;
  /** Disable the button */
  disabled?: boolean;
  /** Click handler */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /** Optional className */
  className?: string;
}

const OFFSETS: Record<NonNullable<SlideFillButtonProps["direction"]>, { x: string; y: string }> = {
  left: { x: "-101%", y: "0%" },
  right: { x: "101%", y: "0%" },
  up: { x: "0%", y: "101%" },
  down: { x: "0%", y: "-101%" },
};

export function SlideFillButton({
  label = "Get started",
  children,
  direction = "left",
  fillColor = "#f4f4f6",
  fillTextColor = "#09090b",
  duration = 0.35,
  disabled = false,
  onClick,
  className = "",
}: SlideFillButtonProps) {
  const prefersReducedMotion = useReducedMotion();
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const active = !disabled && (hovered || focused);
  const from = OFFSETS[direction] ?? OFFSETS.left;

  const handleFocus = (event: React.FocusEvent<HTMLButtonElement>) => {
    let visible = true;
    try {
      visible = event.currentTarget.matches(":focus-visible");
    } catch {
      visible = true;
    }
    setFocused(visible);
  };

  const transition = prefersReducedMotion
    ? { duration: 0 }
    : { duration, ease: [0.22, 1, 0.36, 1] as const };

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      onPointerEnter={(e) => e.pointerType !== "touch" && setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onFocus={handleFocus}
      onBlur={() => setFocused(false)}
      data-active={active || undefined}
      style={
        {
          "--mf-sf-fill": fillColor,
          "--mf-sf-fill-text": fillTextColor,
          "--mf-sf-duration": `${prefersReducedMotion ? 0 : duration}s`,
        } as React.CSSProperties
      }
      className={`${styles.root} ${className}`.trim()}
    >
      <motion.span
        aria-hidden="true"
        className={styles.fill}
        initial={false}
        animate={active ? { x: "0%", y: "0%" } : from}
        transition={transition}
      />
      <span className={styles.label}>{children ?? label}</span>
    </button>
  );
}

.root {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.7rem 1.35rem;
  overflow: hidden;
  isolation: isolate;
  border-radius: 0.625rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  user-select: none;
  transition: border-color var(--mf-sf-duration, 0.35s) ease;
}

.root[data-active] {
  border-color: var(--mf-sf-fill, var(--mf-fg, #f4f4f6));
}

.root:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.fill {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-color: var(--mf-sf-fill, var(--mf-fg, #f4f4f6));
  transform: translateX(-101%);
  pointer-events: none;
}

.label {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  pointer-events: none;
  transition: color var(--mf-sf-duration, 0.35s) cubic-bezier(0.22, 1, 0.36, 1);
}

.root[data-active] .label {
  color: var(--mf-sf-fill-text, var(--mf-bg, #09090b));
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .label {
    transition: none;
  }
}

