"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/flip-card.module.css";

export interface FlipCardProps {
  /** Custom front face content (overrides frontTitle/frontText) */
  front?: React.ReactNode;
  /** Custom back face content (overrides backTitle/backText) */
  back?: React.ReactNode;
  /** Front face heading used when `front` is not provided */
  frontTitle?: string;
  /** Front face text used when `front` is not provided */
  frontText?: string;
  /** Back face heading used when `back` is not provided */
  backTitle?: string;
  /** Back face text used when `back` is not provided */
  backText?: string;
  /** What flips the card with a pointer (Enter/Space always flips) */
  trigger?: "hover" | "click";
  /** Rotation axis */
  axis?: "y" | "x";
  /** Card width in pixels */
  width?: number;
  /** Card height in pixels */
  height?: number;
  /** Optional className */
  className?: string;
}

export function FlipCard({
  front,
  back,
  frontTitle = "Flip Card",
  frontText = "Hover, click or press Enter to turn me over.",
  backTitle = "Spring-driven 3D",
  backText = "Perspective, backface culling and a tuned spring. Press Enter again to flip back.",
  trigger = "hover",
  axis = "y",
  width = 288,
  height = 224,
  className = "",
}: FlipCardProps) {
  const prefersReducedMotion = useReducedMotion();
  const [flipped, setFlipped] = React.useState(false);
  const lastPointer = React.useRef("mouse");
  const rotateKey = axis === "x" ? "rotateX" : "rotateY";

  const onPointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
    lastPointer.current = e.pointerType;
    if (trigger === "hover" && e.pointerType !== "touch") setFlipped(true);
  };
  const onPointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
    if (trigger === "hover" && e.pointerType !== "touch") setFlipped(false);
  };
  const onClick = () => {
    if (trigger === "click" || lastPointer.current === "touch") setFlipped((f) => !f);
  };
  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      setFlipped((f) => !f);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={flipped}
      aria-roledescription="flip card"
      onPointerEnter={onPointerEnter}
      onPointerDown={(e) => {
        lastPointer.current = e.pointerType;
      }}
      onPointerLeave={onPointerLeave}
      onClick={onClick}
      onKeyDown={onKeyDown}
      style={
        {
          "--mf-fc-w": `${width}px`,
          "--mf-fc-h": `${height}px`,
        } as React.CSSProperties
      }
      className={`${styles.root} ${className}`.trim()}
    >
      <motion.div
        className={styles.inner}
        initial={false}
        animate={{ [rotateKey]: flipped ? 180 : 0 }}
        transition={prefersReducedMotion ? { duration: 0 } : { type: "spring", stiffness: 120, damping: 16 }}
      >
        <div className={`${styles.face} ${styles.front}`} aria-hidden={flipped}>
          {front ?? (
            <>
              <span className={styles.badge} aria-hidden="true">
                <svg viewBox="0 0 24 24" width="18" height="18">
                  <path d="M4 12a8 8 0 0 1 14-5.3M20 12a8 8 0 0 1-14 5.3M18 3v4h-4M6 21v-4h4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </span>
              <h3 className={styles.title}>{frontTitle}</h3>
              <p className={styles.text}>{frontText}</p>
            </>
          )}
        </div>
        <div
          className={`${styles.face} ${styles.back}`}
          aria-hidden={!flipped}
          style={{ transform: axis === "x" ? "rotateX(180deg)" : "rotateY(180deg)" }}
        >
          {back ?? (
            <>
              <h3 className={styles.title}>{backTitle}</h3>
              <p className={styles.text}>{backText}</p>
            </>
          )}
        </div>
      </motion.div>
    </div>
  );
}

.root {
  position: relative;
  display: inline-block;
  width: var(--mf-fc-w, 288px);
  max-width: 100%;
  height: var(--mf-fc-h, 224px);
  perspective: 1000px;
  border-radius: 1rem;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.root:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.inner {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
}

.face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 1.5rem;
  box-sizing: border-box;
  border-radius: 1rem;
  text-align: center;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  overflow: hidden;
}

.front {
  background: radial-gradient(120% 90% at 50% 0%, var(--mf-surface-raised, #1b1b22) 0%, var(--mf-surface, #121218) 70%);
  border: 1px solid var(--mf-border, #2e2e38);
  color: var(--mf-fg, #f4f4f6);
}

.back {
  background: linear-gradient(140deg, var(--mf-accent, #38bdf8) 0%, #0ea5e9 100%);
  border: 1px solid var(--mf-accent, #38bdf8);
  color: var(--mf-bg, #09090b);
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  margin-bottom: 0.25rem;
  border-radius: 0.625rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-bg, #09090b);
  color: var(--mf-accent, #38bdf8);
}

.title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.text {
  margin: 0;
  max-width: 16rem;
  font-size: 0.875rem;
  line-height: 1.5;
  opacity: 0.8;
}

@media (prefers-reduced-motion: reduce) {
  .inner {
    transition: none !important;
  }
}

